  -- 10–12 advanced: только целевая лексика (6 монстров); 8 блоков на месте прежних 8
  update classroom_blocks set type='flashcards', payload=$j${"title": "Посмотри карточки, послушай и повтори слова", "page_bg": "https://classroom.wowteach.ru/media/halloween/hw_bg_street.webp", "cards": [{"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436251298_tts_1792436251298.mp3", "audio_tts": {"text": "witch", "voice": "en_US-amy"}}, {"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436253622_tts_1792436253622.mp3", "audio_tts": {"text": "vampire", "voice": "en_US-amy"}}, {"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436256063_tts_1792436256063.mp3", "audio_tts": {"text": "mummy", "voice": "en_US-amy"}}, {"text": "werewolf", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_werewolf.webp", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436258502_tts_1792436258502.mp3", "audio_tts": {"text": "werewolf", "voice": "en_US-amy"}}, {"text": "skeleton", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436260638_tts_1792436260638.mp3", "audio_tts": {"text": "skeleton", "voice": "en_US-amy"}}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436263233_tts_1792436263233.mp3", "audio_tts": {"text": "ghost", "voice": "en_US-amy"}}]}$j$::jsonb where lesson_id=l14 and sort_order=0;
  update classroom_blocks set type='quiz', payload=$j${"title": "🔊 Послушай и выбери картинку", "questions": [{"q": "", "type": "single", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436260638_tts_1792436260638.mp3", "audio_tts": {"text": "skeleton", "voice": "en_US-amy"}, "correct": [0], "options": [{"text": "skeleton", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp"}, {"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}, {"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}]}, {"q": "", "type": "single", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436253622_tts_1792436253622.mp3", "audio_tts": {"text": "vampire", "voice": "en_US-amy"}, "correct": [1], "options": [{"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}, {"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}, {"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp"}]}, {"q": "", "type": "single", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436263233_tts_1792436263233.mp3", "audio_tts": {"text": "ghost", "voice": "en_US-amy"}, "correct": [2], "options": [{"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}, {"text": "werewolf", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_werewolf.webp"}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}]}, {"q": "", "type": "single", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436256063_tts_1792436256063.mp3", "audio_tts": {"text": "mummy", "voice": "en_US-amy"}, "correct": [0], "options": [{"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}, {"text": "skeleton", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp"}]}, {"q": "", "type": "single", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436251298_tts_1792436251298.mp3", "audio_tts": {"text": "witch", "voice": "en_US-amy"}, "correct": [0], "options": [{"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp"}, {"text": "skeleton", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp"}, {"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}]}, {"q": "", "type": "single", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436258502_tts_1792436258502.mp3", "audio_tts": {"text": "werewolf", "voice": "en_US-amy"}, "correct": [2], "options": [{"text": "skeleton", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp"}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}, {"text": "werewolf", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_werewolf.webp"}]}]}$j$::jsonb where lesson_id=l14 and sort_order=1;
  update classroom_blocks set type='match', payload=$j${"title": "Соедини картинку и слово", "pairs": [{"left_image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp", "right": "witch"}, {"left_image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp", "right": "vampire"}, {"left_image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp", "right": "mummy"}, {"left_image": "https://classroom.wowteach.ru/media/halloween/10-12/s_werewolf.webp", "right": "werewolf"}, {"left_image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp", "right": "skeleton"}, {"left_image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp", "right": "ghost"}]}$j$::jsonb where lesson_id=l14 and sort_order=2;
  update classroom_blocks set type='quiz', payload=$j${"title": "Прочитай и выбери, кто это", "questions": [{"q": "She has got a black hat and a broom.", "type": "single", "correct": [2], "options": [{"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}, {"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp"}]}, {"q": "He has got big teeth and a black cape.", "type": "single", "correct": [1], "options": [{"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}, {"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}, {"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}]}, {"q": "He is wrapped in white bandages.", "type": "single", "correct": [2], "options": [{"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp"}, {"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}, {"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}]}, {"q": "He is very hairy and he howls at the moon.", "type": "single", "correct": [2], "options": [{"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}, {"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp"}, {"text": "werewolf", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_werewolf.webp"}]}, {"q": "He has got no skin — only bones!", "type": "single", "correct": [1], "options": [{"text": "witch", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp"}, {"text": "skeleton", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp"}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}]}, {"q": "It is white and you can see through it.", "type": "single", "correct": [1], "options": [{"text": "vampire", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp"}, {"text": "ghost", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp"}, {"text": "mummy", "image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp"}]}]}$j$::jsonb where lesson_id=l14 and sort_order=3;
  update classroom_blocks set type='exact_input', payload=$j${"title": "Переставь буквы по порядку и напиши слово", "items": [{"image": "https://classroom.wowteach.ru/media/halloween/10-12/s_ghost.webp", "prompt": "S O G T H", "accept": ["ghost", "Ghost"]}, {"image": "https://classroom.wowteach.ru/media/halloween/10-12/s_witch.webp", "prompt": "H C W T I", "accept": ["witch", "Witch"]}, {"image": "https://classroom.wowteach.ru/media/halloween/10-12/s_mummy.webp", "prompt": "U M Y M M", "accept": ["mummy", "Mummy"]}, {"image": "https://classroom.wowteach.ru/media/halloween/10-12/s_vampire.webp", "prompt": "P M A E V R I", "accept": ["vampire", "Vampire"]}, {"image": "https://classroom.wowteach.ru/media/halloween/10-12/s_skeleton.webp", "prompt": "T O N S E K L E", "accept": ["skeleton", "Skeleton"]}, {"image": "https://classroom.wowteach.ru/media/halloween/10-12/s_werewolf.webp", "prompt": "F W O E R L E W", "accept": ["werewolf", "Werewolf"]}]}$j$::jsonb where lesson_id=l14 and sort_order=4;
  update classroom_blocks set type='exact_input', payload=$j${"title": "🔊 Послушай и напиши слово", "items": [{"prompt": "", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436253622_tts_1792436253622.mp3", "audio_tts": {"text": "vampire", "voice": "en_US-amy"}, "accept": ["vampire", "Vampire"]}, {"prompt": "", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436263233_tts_1792436263233.mp3", "audio_tts": {"text": "ghost", "voice": "en_US-amy"}, "accept": ["ghost", "Ghost"]}, {"prompt": "", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436258502_tts_1792436258502.mp3", "audio_tts": {"text": "werewolf", "voice": "en_US-amy"}, "accept": ["werewolf", "Werewolf"]}, {"prompt": "", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436251298_tts_1792436251298.mp3", "audio_tts": {"text": "witch", "voice": "en_US-amy"}, "accept": ["witch", "Witch"]}, {"prompt": "", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436256063_tts_1792436256063.mp3", "audio_tts": {"text": "mummy", "voice": "en_US-amy"}, "accept": ["mummy", "Mummy"]}, {"prompt": "", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/uploads/1792436260638_tts_1792436260638.mp3", "audio_tts": {"text": "skeleton", "voice": "en_US-amy"}, "accept": ["skeleton", "Skeleton"]}]}$j$::jsonb where lesson_id=l14 and sort_order=5;
  update classroom_blocks set type='gaps', payload=$j${"mode": "drag", "title": "The Golden Pumpkin: расставь слова по пропускам", "text": "Last night someone stole the Golden Pumpkin! The police talked to six suspects. The __witch__ was flying on her broom. The __vampire__ was sleeping in his coffin. The __mummy__ was at the museum in his bandages. The __werewolf__ was howling at the moon. The __skeleton__ was dancing — rattle, rattle! And the __ghost__? Nobody could see him… Who is the thief?"}$j$::jsonb where lesson_id=l14 and sort_order=6;
  update classroom_blocks set type='speaking', payload=$j${"title": "🎤 Как ты празднуешь Хэллоуин?", "image": "https://classroom.wowteach.ru/media/halloween/10-12/hw_suspect.webp", "html": "<p>Прочитай пример. Нажми на запись и расскажи, как ты празднуешь Хэллоуин: 3–4 предложения.</p><p><i>I have a costume — I'm a vampire. I eat mummy hot dogs and pasta. I watch films and listen to ghost stories.</i></p><p><b>What is your costume? What do you eat? What do you do?</b></p>"}$j$::jsonb where lesson_id=l14 and sort_order=7;
end $mig$;
